template <typename V, int N = 10>
struct TemplateA {};

template <typename U, int M = 5>
struct DefaultTemplate {};

template <
    typename TParam,
    template <typename X, int M = 5> class TT = TemplateA
>
struct Container {
    // If TT is TemplateA (default), TemplateA's default (N=10) wins
    // over the M=5 specified in Container's definition.
    using DefaultUse = TT<TParam>;
};

